def find_pairs_pq(S):
    pairs = []
    # Since p+q=S and S=800 (even), p and q must both be odd (since p=2 => q=798, not prime)
    # We only need to check primes p up to S/2 = 400.
    for p in range(3, S // 2 + 1, 2):
        if is_prime(p):
            q = S - p
            if q > p and is_prime(q):
                pairs.append((p, q))
    return pairs

